import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  AccessibilityInfo,
  PanResponder,
  View,
  type ViewStyle,
} from "react-native";
import {
  AlphaType,
  BlendMode,
  Canvas,
  ColorType,
  FilterMode,
  Group,
  MipmapMode,
  Picture,
  Rect,
  Skia,
  TileMode,
  type SkImage,
  type SkPaint,
  type SkPicture,
  type SkRuntimeEffect,
  type SkShader,
} from "@shopify/react-native-skia";
import {
  ASH_STRIDE,
  BURN_DEFAULTS,
  EMBER_STRIDE,
  burnPointerDown,
  burnPointerUp,
  createBurn,
  packBurn,
  startRestore,
  stepBurn,
  type BurnConfig,
  type BurnState,
} from "./burnMath";
import { CARD_H, CARD_W } from "./burnDesign";

export type BurnDismissProps = {
  /** The card to burn, drawn once with Skia (see Example). */
  image: SkImage;
  /** Card size in layout points. */
  width?: number;
  height?: number;
  /** Burn field resolution. */
  cols?: number;
  rows?: number;
  /** Runs the fire about five times slower. Ignored while Reduce Motion is on. */
  slowMotion?: boolean;
  reducedMotion?: boolean;
  /** Increment to restore the card (the burn front rewinds). */
  restoreTick?: number;
  /** Fired with 'ignite', 'release' and 'restore' (hook haptics here). */
  onFeedback?: (event: "ignite" | "release" | "restore") => void;
  /** Called once the card has burned away completely. */
  onDismissed?: () => void;
  label?: string;
  style?: ViewStyle;
};

const SKSL = `
uniform shader sceneSharp;
uniform shader burnTex;
uniform float2 dstSize;
uniform float2 texSize;
uniform float2 sceneSize;
uniform float time;

float hash21(float2 p) {
  p = fract(p * float2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
float vnoise(float2 p) {
  float2 i = floor(p);
  float2 f = fract(p);
  float2 u = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + float2(1.0, 0.0));
  float c = hash21(i + float2(0.0, 1.0));
  float d = hash21(i + float2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
float fbm(float2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int k = 0; k < 4; k++) {
    v += a * vnoise(p);
    p *= 2.03;
    a *= 0.5;
  }
  return v;
}

half4 main(float2 xy) {
  float2 uv = xy / dstSize;
  float2 tuv = uv * texSize;
  float4 bt = burnTex.eval(tuv);
  float burn = bt.r;
  float gflick = bt.g;
  float crack = bt.b;

  // Noise-warped front: the edge eats in bites, not a circle.
  float warp = fbm(uv * float2(7.0, 9.0) + float2(0.0, time * 0.05));
  float bw = burn + (warp - 0.5) * 0.22 * smoothstep(-0.06, 0.3, burn);

  half3 scene = sceneSharp.eval(uv * sceneSize).rgb;

  // Paper fibre on the unburnt card.
  float fibre = fbm(uv * float2(46.0, 7.0));
  scene *= 0.965 + 0.07 * fibre;

  if (bw > 0.001) {
    // Scorch: paper browns ahead of the char.
    float scorch = smoothstep(0.001, 0.10, bw) * (1.0 - smoothstep(0.10, 0.30, bw));
    scene = mix(scene, half3(0.45, 0.28, 0.12), scorch * 0.55);

    // Glow band: white -> yellow -> orange -> red across the burning edge.
    float gb = smoothstep(0.02, 0.06, bw) * (1.0 - smoothstep(0.16, 0.34, bw));
    half3 glowCol = half3(1.0, 0.97, 0.86);
    glowCol = mix(glowCol, half3(1.0, 0.82, 0.24), smoothstep(0.02, 0.10, bw));
    glowCol = mix(glowCol, half3(1.0, 0.45, 0.10), smoothstep(0.10, 0.20, bw));
    glowCol = mix(glowCol, half3(0.78, 0.12, 0.02), smoothstep(0.20, 0.34, bw));
    float glow = gb * (0.35 + 0.65 * gflick);
    scene = mix(scene, glowCol * 1.35, clamp(glow * 1.25, 0.0, 1.0));

    // Char: blackened fibre with hot cracks.
    float ch = smoothstep(0.30, 0.48, bw);
    float streak = fbm(float2(uv.x * 60.0, uv.y * 9.0));
    half3 charCol = mix(half3(0.16, 0.10, 0.06), half3(0.05, 0.03, 0.02), smoothstep(0.48, 0.9, bw));
    charCol *= 0.85 + 0.3 * streak;
    charCol += half3(0.9, 0.25, 0.05) * crack * 0.8;
    scene = mix(scene, charCol, ch);

    // Curl: the charred rim lifts - lit crest, then shadow at the eaten edge.
    float2 e = 1.0 / texSize;
    float bx = burnTex.eval(tuv + float2(e.x, 0.0)).r - burnTex.eval(tuv - float2(e.x, 0.0)).r;
    float by = burnTex.eval(tuv + float2(0.0, e.y)).r - burnTex.eval(tuv - float2(0.0, e.y)).r;
    float crest = smoothstep(0.80, 0.90, bw) * (1.0 - smoothstep(0.90, 0.965, bw));
    float litEdge = clamp((bx * -0.55 + by * -0.83) * 6.0, -1.0, 1.0);
    scene += half3(0.5, 0.34, 0.18) * crest * max(litEdge, 0.0);
    scene *= 1.0 - 0.55 * crest * max(-litEdge, 0.0);

    // Ash-grey dusting at the consumed rim.
    float rim = smoothstep(0.90, 0.965, bw);
    scene = mix(scene, half3(0.32, 0.30, 0.28), rim * 0.65 * (1.0 - smoothstep(0.965, 0.99, bw)));
  }

  // Hole: the paper is gone.
  float alpha = 1.0 - smoothstep(0.965, 0.995, bw);
  return half4(scene, alpha);
}
`;

// Compiled once per app lifetime; null means SkSL unsupported -> static card.
let cachedEffect: SkRuntimeEffect | null | undefined;
function getEffect(): SkRuntimeEffect | null {
  if (cachedEffect === undefined) cachedEffect = Skia.RuntimeEffect.Make(SKSL);
  return cachedEffect;
}

type Frame = { paint: SkPaint; picture: SkPicture };

function lerp(a: number, b: number, t: number) {
  return a + (b - a) * t;
}

function emberColor(t: number): [number, number, number] {
  if (t < 0.35) return [lerp(1, 1, t / 0.35), lerp(0.95, 0.6, t / 0.35), lerp(0.75, 0.18, t / 0.35)];
  if (t < 0.75) {
    const u = (t - 0.35) / 0.4;
    return [1, lerp(0.6, 0.18, u), lerp(0.18, 0.03, u)];
  }
  const u = (t - 0.75) / 0.25;
  return [lerp(1, 0.4, u), lerp(0.18, 0.06, u), lerp(0.03, 0.02, u)];
}

/** Draw the ember and ash layers into one picture for this frame. */
function recordParticles(sim: BurnState, width: number, height: number): SkPicture {
  const recorder = Skia.PictureRecorder();
  const canvas = recorder.beginRecording(Skia.XYWHRect(0, 0, width, height));
  const glow = Skia.Paint();
  glow.setAntiAlias(true);
  glow.setBlendMode(BlendMode.Plus);
  const core = Skia.Paint();
  core.setAntiAlias(true);
  core.setBlendMode(BlendMode.Plus);
  const ash = Skia.Paint();
  ash.setAntiAlias(true);
  for (let s = 0; s < sim.emberCount; s++) {
    const i = s * EMBER_STRIDE;
    const t = sim.embers[i + 4] / sim.embers[i + 5];
    const flick = 0.72 + 0.28 * Math.sin(sim.clock * 21 + sim.embers[i + 7]);
    const fade = t > 0.8 ? (1 - t) / 0.2 : 1;
    const [r, g, b] = emberColor(t);
    const x = sim.embers[i];
    const y = sim.embers[i + 1];
    const rad = sim.embers[i + 6] * (1 - t * 0.55);
    glow.setColor(Skia.Color(`rgba(${Math.round(r * 255)},${Math.round(g * 255)},${Math.round(b * 255)},${(0.34 * flick * fade).toFixed(3)})`));
    canvas.drawCircle(x, y, rad * 3.1, glow);
    core.setColor(Skia.Color(`rgba(255,${Math.round(lerp(240, 120, t))},${Math.round(lerp(190, 40, t))},${(0.95 * fade).toFixed(3)})`));
    canvas.drawCircle(x, y, Math.max(0.4, rad), core);
  }
  for (let s = 0; s < sim.ashCount; s++) {
    const i = s * ASH_STRIDE;
    const t = sim.ash[i + 4] / sim.ash[i + 5];
    const fade = t > 0.72 ? (1 - t) / 0.28 : 1;
    ash.setColor(Skia.Color(`rgba(74,60,46,${(0.85 * fade).toFixed(3)})`));
    canvas.save();
    canvas.translate(sim.ash[i], sim.ash[i + 1]);
    canvas.rotate((sim.ash[i + 7] * 180) / 3.1416);
    const w = sim.ash[i + 6];
    canvas.drawRect(Skia.XYWHRect(-w, -w * 0.6, w * 2, w * 1.2), ash);
    canvas.restore();
  }
  const picture = recorder.finishRecordingAsPicture();
  glow.dispose();
  core.dispose();
  ash.dispose();
  return picture;
}

export function BurnDismiss({
  image,
  width = CARD_W,
  height = CARD_H,
  cols = 96,
  rows = 128,
  slowMotion = false,
  reducedMotion,
  restoreTick = 0,
  onFeedback,
  onDismissed,
  label = "A postcard you can burn away. Touch and hold to ignite the paper at your finger, drag to spread the fire, and restore to bring it back",
  style,
}: BurnDismissProps) {
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;

  const cfg: BurnConfig = useMemo(() => ({ cols, rows, width, height }), [cols, rows, width, height]);
  const opts = useMemo(() => BURN_DEFAULTS, []);
  const simRef = useRef<BurnState | null>(null);
  if (!simRef.current) simRef.current = createBurn(cfg, opts);
  const bytesRef = useRef<Uint8Array | null>(null);
  if (!bytesRef.current) bytesRef.current = new Uint8Array(cols * rows * 4);

  const effect = getEffect();
  const sceneShader = useMemo(() => {
    if (!effect) return null;
    return image.makeShaderOptions(TileMode.Clamp, TileMode.Clamp, FilterMode.Linear, MipmapMode.None);
  }, [effect, image]);
  useEffect(() => () => sceneShader?.dispose(), [sceneShader]);

  const [frame, setFrame] = useState<Frame | null>(null);
  const latest = useRef({ slowMotion, reduce, onFeedback, onDismissed });
  latest.current = { slowMotion, reduce, onFeedback, onDismissed };
  const restoreSeen = useRef(restoreTick);

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => {
        if (alive) setSystemReduce(v);
      })
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);

  // A size or grid change rebuilds the card unburnt.
  useEffect(() => {
    simRef.current = createBurn(cfg, opts);
    bytesRef.current = new Uint8Array(cfg.cols * cfg.rows * 4);
  }, [cfg, opts]);

  // External restore requests.
  useEffect(() => {
    if (restoreTick !== restoreSeen.current) {
      restoreSeen.current = restoreTick;
      const sim = simRef.current;
      if (sim && sim.mode === 1) {
        startRestore(sim);
        latest.current.onFeedback?.("restore");
      }
    }
  }, [restoreTick]);

  // JS-thread frame loop: steps the sim, packs the burn texture and publishes
  // a fresh runtime-shader paint plus the particle layer. The per-frame
  // Fabric commits keep the render pipeline awake on a quiet Android screen,
  // the same mechanism as Fogged Glass, so no separate keep-alive is needed.
  useEffect(() => {
    if (!effect || !sceneShader) return;
    let alive = true;
    let last = 0;
    let dismissed = false;
    let prevImage: SkImage | null = null;
    let prevBurnShader: SkShader | null = null;
    let prev: Frame | null = null;
    const loop = (now: number) => {
      if (!alive) return;
      const sim = simRef.current!;
      const dt = last ? Math.min(48, now - last) / 1000 : 1 / 60;
      last = now;
      if (!latest.current.reduce) {
        stepBurn(sim, cfg, dt * (latest.current.slowMotion ? 0.22 : 1), opts);
      }
      if (!dismissed && sim.burnt >= cfg.cols * cfg.rows) {
        dismissed = true;
        latest.current.onDismissed?.();
      }
      const bytes = packBurn(sim, cfg, bytesRef.current!);
      const burnImage = Skia.Image.MakeImage(
        { width: cfg.cols, height: cfg.rows, colorType: ColorType.RGBA_8888, alphaType: AlphaType.Unpremul },
        Skia.Data.fromBytes(bytes),
        cfg.cols * 4,
      );
      if (burnImage) {
        const burnShader = burnImage.makeShaderOptions(TileMode.Clamp, TileMode.Clamp, FilterMode.Linear, MipmapMode.None);
        const next = Skia.Paint();
        next.setShader(
          effect.makeShaderWithChildren(
            [0, 0, cfg.width, cfg.height, cfg.cols, cfg.rows, image.width(), image.height(), sim.clock],
            [sceneShader, burnShader],
          ),
        );
        const picture = recordParticles(sim, cfg.width, cfg.height);
        setFrame({ paint: next, picture });
        prev?.paint.dispose();
        prev?.picture.dispose();
        prevBurnShader?.dispose();
        prevImage?.dispose();
        prev = { paint: next, picture };
        prevBurnShader = burnShader;
        prevImage = burnImage;
      }
      requestAnimationFrame(loop);
    };
    const raf = requestAnimationFrame(loop);
    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      prev?.paint.dispose();
      prev?.picture.dispose();
      prevBurnShader?.dispose();
      prevImage?.dispose();
    };
  }, [effect, sceneShader, cfg, opts, image]);

  const pan = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => !latest.current.reduce,
        onPanResponderGrant: (evt) => {
          const sim = simRef.current;
          if (sim) burnPointerDown(sim, cfg, evt.nativeEvent.locationX, evt.nativeEvent.locationY, opts);
          latest.current.onFeedback?.("ignite");
        },
        onPanResponderMove: (evt) => {
          const sim = simRef.current;
          if (sim) burnPointerDown(sim, cfg, evt.nativeEvent.locationX, evt.nativeEvent.locationY, opts);
        },
        onPanResponderRelease: () => {
          const sim = simRef.current;
          if (sim) burnPointerUp(sim);
          latest.current.onFeedback?.("release");
        },
        onPanResponderTerminate: () => {
          const sim = simRef.current;
          if (sim) burnPointerUp(sim);
        },
        onPanResponderTerminationRequest: () => false,
      }),
    [cfg, opts],
  );

  return (
    <View
      style={[{ width, height, borderRadius: 18, overflow: "hidden", backgroundColor: "#241d16" }, style]}
      accessibilityLabel={label}
      accessibilityRole="image"
      {...pan.panHandlers}
    >
      <Canvas pointerEvents="none" style={{ width, height }}>
        <Group>
          {frame ? (
            <>
              <Rect x={0} y={0} width={width} height={height} paint={frame.paint} />
              <Picture picture={frame.picture} />
            </>
          ) : (
            <Rect x={0} y={0} width={width} height={height} color="#f4eddc" />
          )}
        </Group>
      </Canvas>
    </View>
  );
}

// Pure combustion model for Burn Dismiss. A postcard ignites where the
// finger lands: a noise-warped burn front creeps outward, paper chars behind
// it and is eaten away, embers rise on turbulent air and ash flutters down.
// Holding the finger feeds the fire; Restore runs the same front backward
// because every cell's burn level is a pure function of the sim clock:
// burn_i(t) = clamp((t - igniteT_i) * rate_i, 0, 1). No Math.random anywhere:
// a seeded generator keeps web, native and tests in agreement frame for
// frame. Every function is a worklet so the sim can run on either thread.

export type BurnConfig = {
  cols: number;
  rows: number;
  /** Card size in px. */
  width: number;
  height: number;
};

export const BURN_DEFAULTS = {
  /** Seconds for one cell to burn through, before the fuel multiplier. */
  burnTime: 1.15,
  /** Heat a burning neighbour pumps into a cell per second per unit burn. */
  spreadRate: 75,
  /** Burn level a cell must pass before it heats its neighbours. */
  spreadAfter: 0.05,
  /** Diagonal neighbours heat at this fraction of the edge neighbours. */
  diagSpread: 0.55,
  /** Heat at which a cell ignites. */
  igniteAtHeat: 1,
  /** Fire climbs: upward spread multiplier / downward multiplier. */
  upDraft: 1.5,
  downDraft: 0.65,
  /** Finger heat injection per second inside the hold radius. */
  injectRate: 16,
  /** Hold radius, px. */
  holdRadius: 15,
  /** Instantly lit core under a fresh touch, px. */
  sparkRadius: 3,
  /** Restore plays the clock backward at this multiple of forward speed. */
  restoreSpeed: 2.1,
  /** Ember spawn probability per frontier cell per second. */
  emberRate: 0.09,
  /** Ash spawn probability per freshly charred cell per second. */
  ashRate: 0.10,
  maxEmbers: 170,
  maxAsh: 90,
  /** Fixed timestep ceiling for the sim. */
  fixedDt: 1 / 90,
};

export type BurnOptions = typeof BURN_DEFAULTS;

/** Ember slot stride: x, y, vx, vy, life, maxLife, size, seed. */
export const EMBER_STRIDE = 8;
/** Ash slot stride: x, y, vx, vy, life, maxLife, size, rot, spin, seed. */
export const ASH_STRIDE = 10;

export type BurnState = {
  /** Clock the whole burn is a function of, seconds. */
  clock: number;
  /** Per cell: ignition time on the clock, -1 while unburnt. Row-major. */
  igniteT: Float32Array;
  /** Per cell: burn-through rate locked in at ignition. */
  rate: Float32Array;
  /** Per cell: accumulated heat toward ignition. */
  heat: Float32Array;
  /** Per cell: paper fuel multiplier from low-frequency noise, fixed. */
  fuel: Float32Array;
  /** Ember slots, EMBER_STRIDE floats each. */
  embers: Float32Array;
  emberCount: number;
  /** Ash slots, ASH_STRIDE floats each. */
  ash: Float32Array;
  ashCount: number;
  /** 0 idle, 1 burning, 2 restoring. */
  mode: number;
  /** Seeded PRNG state. */
  seed: number;
  /** Held finger, in px; active gates heat injection. */
  px: number;
  py: number;
  holding: number;
  /** Book-keeping for spawn throttling and statistics. */
  burnt: number;
  minIgniteT: number;
  /** Scratch for heat spreading, so no step allocates. */
  scratch: Float32Array;
};

export function hash01(i: number, s: number): number {
  'worklet';
  let h = (i * 374761393 + s * 668265263) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

export function rand(s: BurnState): number {
  'worklet';
  s.seed = (Math.imul(s.seed, 1664525) + 1013904223) | 0;
  return ((s.seed >>> 9) & 0x7fffff) / 8388608;
}

function vnoise(x: number, y: number, seed: number): number {
  'worklet';
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const xf = x - xi;
  const yf = y - yi;
  const u = xf * xf * (3 - 2 * xf);
  const v = yf * yf * (3 - 2 * yf);
  const a = hash01(xi * 7919 + yi * 104729, seed);
  const b = hash01((xi + 1) * 7919 + yi * 104729, seed);
  const c = hash01(xi * 7919 + (yi + 1) * 104729, seed);
  const d = hash01((xi + 1) * 7919 + (yi + 1) * 104729, seed);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}

/** Fractal value noise, 4 octaves, ~0..1. */
export function fbm2(x: number, y: number, seed: number): number {
  'worklet';
  let v = 0;
  let amp = 0.5;
  let fx = x;
  let fy = y;
  for (let o = 0; o < 4; o++) {
    v += amp * vnoise(fx, fy, seed + o * 131);
    fx *= 2.03;
    fy *= 2.03;
    amp *= 0.5;
  }
  return v;
}

export function createBurn(cfg: BurnConfig, opts: BurnOptions, seed = 20261124): BurnState {
  'worklet';
  const n = cfg.cols * cfg.rows;
  const fuel = new Float32Array(n);
  for (let r = 0; r < cfg.rows; r++) {
    for (let c = 0; c < cfg.cols; c++) {
      // Low-frequency paper grain: some patches burn faster than others.
      fuel[r * cfg.cols + c] = 0.82 + 0.55 * fbm2(c * 0.09, r * 0.09, seed);
    }
  }
  const igniteT = new Float32Array(n);
  igniteT.fill(-1);
  return {
    clock: 0,
    igniteT,
    rate: new Float32Array(n),
    heat: new Float32Array(n),
    fuel,
    embers: new Float32Array(opts.maxEmbers * EMBER_STRIDE),
    emberCount: 0,
    ash: new Float32Array(opts.maxAsh * ASH_STRIDE),
    ashCount: 0,
    mode: 0,
    seed: seed ^ 0x5bd1e995,
    px: 0,
    py: 0,
    holding: 0,
    burnt: 0,
    minIgniteT: -1,
    scratch: new Float32Array(n),
  };
}

/** Burn level of a cell on the reversible clock. */
export function burnAt(sim: BurnState, i: number): number {
  'worklet';
  const t0 = sim.igniteT[i];
  if (t0 < 0) return 0;
  const b = (sim.clock - t0) * sim.rate[i];
  return b < 0 ? 0 : b > 1 ? 1 : b;
}

function igniteCell(sim: BurnState, cfg: BurnConfig, c: number, r: number, opts: BurnOptions) {
  'worklet';
  const i = r * cfg.cols + c;
  if (sim.igniteT[i] >= 0) return;
  sim.igniteT[i] = sim.clock;
  sim.rate[i] = (0.9 + 0.2 * hash01(i, 77)) / (opts.burnTime * sim.fuel[i]);
  if (sim.minIgniteT < 0) sim.minIgniteT = sim.clock;
  sim.mode = 1;
}

/** Touch down or drag: light the core at once and prime a heat ring. */
export function burnPointerDown(sim: BurnState, cfg: BurnConfig, x: number, y: number, opts: BurnOptions) {
  'worklet';
  // A fresh touch after a partial restore drops the un-burnt future, so the
  // new fire spreads by heat like any other.
  if (sim.mode === 2 || sim.mode === 0) {
    const n = cfg.cols * cfg.rows;
    for (let i = 0; i < n; i++) {
      if (sim.igniteT[i] >= 0 && sim.igniteT[i] > sim.clock) {
        sim.igniteT[i] = -1;
        sim.rate[i] = 0;
        sim.heat[i] = 0;
      }
    }
    if (sim.mode === 2) sim.mode = 1;
  }
  sim.px = x;
  sim.py = y;
  sim.holding = 1;
  const cw = cfg.width / cfg.cols;
  const ch = cfg.height / cfg.rows;
  const cc = Math.floor(x / cw);
  const cr = Math.floor(y / ch);
  const spark = Math.max(1, Math.round(opts.sparkRadius / cw));
  for (let dr = -spark; dr <= spark; dr++) {
    for (let dc = -spark; dc <= spark; dc++) {
      const c = cc + dc;
      const r = cr + dr;
      if (c < 0 || r < 0 || c >= cfg.cols || r >= cfg.rows) continue;
      igniteCell(sim, cfg, c, r, opts);
    }
  }
  const ring = Math.ceil(opts.holdRadius / cw);
  for (let dr = -ring; dr <= ring; dr++) {
    for (let dc = -ring; dc <= ring; dc++) {
      const c = cc + dc;
      const r = cr + dr;
      if (c < 0 || r < 0 || c >= cfg.cols || r >= cfg.rows) continue;
      const d = Math.hypot(dc * cw, dr * ch);
      if (d < opts.holdRadius) {
        const i = r * cfg.cols + c;
        sim.heat[i] = Math.max(sim.heat[i], 0.55 * (1 - d / opts.holdRadius));
      }
    }
  }
}

export function burnPointerMove(sim: BurnState, x: number, y: number) {
  'worklet';
  sim.px = x;
  sim.py = y;
}

export function burnPointerUp(sim: BurnState) {
  'worklet';
  sim.holding = 0;
}

/** Begin restoring the card: the clock runs backward from the burn's peak. */
export function startRestore(sim: BurnState) {
  'worklet';
  if (sim.mode === 1 && sim.burnt >= 0) sim.mode = 2;
  sim.holding = 0;
}

export function burntFraction(sim: BurnState): number {
  'worklet';
  return sim.burnt / sim.igniteT.length;
}

function spawnEmber(sim: BurnState, x: number, y: number, opts: BurnOptions) {
  'worklet';
  if (sim.emberCount >= opts.maxEmbers) return;
  const i = sim.emberCount * EMBER_STRIDE;
  sim.emberCount += 1;
  const e = sim.embers;
  e[i] = x;
  e[i + 1] = y;
  e[i + 2] = (rand(sim) - 0.5) * 14;
  e[i + 3] = -18 - rand(sim) * 42;
  e[i + 4] = 0;
  e[i + 5] = 1.1 + rand(sim) * 1.2;
  e[i + 6] = 1.1 + rand(sim) * 1.6;
  e[i + 7] = rand(sim) * 100;
}

function spawnAsh(sim: BurnState, x: number, y: number, opts: BurnOptions) {
  'worklet';
  if (sim.ashCount >= opts.maxAsh) return;
  const i = sim.ashCount * ASH_STRIDE;
  sim.ashCount += 1;
  const a = sim.ash;
  a[i] = x;
  a[i + 1] = y;
  a[i + 2] = (rand(sim) - 0.5) * 10;
  a[i + 3] = 6 + rand(sim) * 14;
  a[i + 4] = 0;
  a[i + 5] = 2.2 + rand(sim) * 1.8;
  a[i + 6] = 1.6 + rand(sim) * 2.2;
  a[i + 7] = rand(sim) * 6.28;
  a[i + 8] = (rand(sim) - 0.5) * 5;
  a[i + 9] = rand(sim) * 100;
}

function killEmber(sim: BurnState, slot: number) {
  'worklet';
  const last = sim.emberCount - 1;
  if (slot !== last) {
    sim.embers.copyWithin(slot * EMBER_STRIDE, last * EMBER_STRIDE, (last + 1) * EMBER_STRIDE);
  }
  sim.emberCount = last;
}

function killAsh(sim: BurnState, slot: number) {
  'worklet';
  const last = sim.ashCount - 1;
  if (slot !== last) {
    sim.ash.copyWithin(slot * ASH_STRIDE, last * ASH_STRIDE, (last + 1) * ASH_STRIDE);
  }
  sim.ashCount = last;
}

function stepParticles(sim: BurnState, cfg: BurnConfig, dt: number) {
  'worklet';
  const e = sim.embers;
  for (let s = 0; s < sim.emberCount; s++) {
    const i = s * EMBER_STRIDE;
    e[i + 4] += dt;
    if (e[i + 4] >= e[i + 5]) {
      killEmber(sim, s);
      s -= 1;
      continue;
    }
    // Turbulence: curl-ish drift from noise, buoyant rise, light drag.
    const t = sim.clock * 1.6 + e[i + 7];
    e[i + 2] += (vnoise(e[i] * 0.045 + t, e[i + 1] * 0.045, 911) - 0.5) * 130 * dt;
    e[i + 3] += (vnoise(e[i] * 0.045, e[i + 1] * 0.045 - t, 912) - 0.62) * 60 * dt;
    e[i + 2] *= 1 - 0.7 * dt;
    e[i + 3] *= 1 - 0.25 * dt;
    if (e[i + 3] < -70) e[i + 3] = -70;
    e[i] += e[i + 2] * dt;
    e[i + 1] += e[i + 3] * dt;
    if (e[i + 1] < -20) {
      killEmber(sim, s);
      s -= 1;
    }
  }
  const a = sim.ash;
  for (let s = 0; s < sim.ashCount; s++) {
    const i = s * ASH_STRIDE;
    a[i + 4] += dt;
    if (a[i + 4] >= a[i + 5] || a[i + 1] > cfg.height + 24) {
      killAsh(sim, s);
      s -= 1;
      continue;
    }
    // Flutter: side sway and tumbling fall.
    a[i + 7] += a[i + 8] * dt;
    a[i] += (a[i + 2] + Math.sin(a[i + 4] * 5 + a[i + 9]) * 9) * dt;
    a[i + 1] += a[i + 3] * (0.85 + 0.3 * Math.sin(a[i + 4] * 3 + a[i + 9])) * dt;
  }
}

/** One fixed step forward (or backward while restoring). */
function step(sim: BurnState, cfg: BurnConfig, dt: number, opts: BurnOptions) {
  'worklet';
  const n = cfg.cols * cfg.rows;
  const cw = cfg.width / cfg.cols;
  const ch = cfg.height / cfg.rows;

  if (sim.mode === 2) {
    // Restore: rewind the clock until nothing was ever lit.
    sim.clock -= dt * opts.restoreSpeed;
    if (sim.minIgniteT < 0 || sim.clock <= sim.minIgniteT) {
      sim.igniteT.fill(-1);
      sim.heat.fill(0);
      sim.clock = 0;
      sim.mode = 0;
      sim.burnt = 0;
      sim.minIgniteT = -1;
    } else {
      let burnt = 0;
      for (let i = 0; i < n; i++) if (burnAt(sim, i) >= 1) burnt += 1;
      sim.burnt = burnt;
    }
    stepParticles(sim, cfg, dt);
    return;
  }

  if (sim.mode !== 1) {
    stepParticles(sim, cfg, dt);
    return;
  }

  sim.clock += dt;

  // Held finger keeps feeding the fire.
  if (sim.holding === 1) {
    const cc = Math.floor(sim.px / cw);
    const cr = Math.floor(sim.py / ch);
    const ring = Math.ceil(opts.holdRadius / cw);
    for (let dr = -ring; dr <= ring; dr++) {
      for (let dc = -ring; dc <= ring; dc++) {
        const c = cc + dc;
        const r = cr + dr;
        if (c < 0 || r < 0 || c >= cfg.cols || r >= cfg.rows) continue;
        const d = Math.hypot(dc * cw, dr * ch);
        if (d < opts.holdRadius) {
          const i = r * cfg.cols + c;
          sim.heat[i] += opts.injectRate * (1 - d / opts.holdRadius) * dt;
          if (sim.heat[i] >= opts.igniteAtHeat) igniteCell(sim, cfg, c, r, opts);
        }
      }
    }
  }

  // Front propagation: burning cells heat their 4-neighbours; fire climbs.
  const add = sim.scratch;
  let burnt = 0;
  for (let r = 0; r < cfg.rows; r++) {
    for (let c = 0; c < cfg.cols; c++) {
      const i = r * cfg.cols + c;
      const b = burnAt(sim, i);
      if (b >= 1) {
        burnt += 1;
        continue;
      }
      if (sim.igniteT[i] < 0 || b < opts.spreadAfter) continue;
      const feed = opts.spreadRate * (b - opts.spreadAfter) * dt;
      const diag = feed * opts.diagSpread;
      if (c > 0) add[i - 1] += feed;
      if (c < cfg.cols - 1) add[i + 1] += feed;
      if (r > 0) add[i - cfg.cols] += feed * opts.upDraft;
      if (r < cfg.rows - 1) add[i + cfg.cols] += feed * opts.downDraft;
      if (c > 0 && r > 0) add[i - cfg.cols - 1] += diag * opts.upDraft;
      if (c < cfg.cols - 1 && r > 0) add[i - cfg.cols + 1] += diag * opts.upDraft;
      if (c > 0 && r < cfg.rows - 1) add[i + cfg.cols - 1] += diag * opts.downDraft;
      if (c < cfg.cols - 1 && r < cfg.rows - 1) add[i + cfg.cols + 1] += diag * opts.downDraft;
    }
  }
  for (let i = 0; i < n; i++) {
    if (add[i] === 0) continue;
    if (sim.igniteT[i] >= 0) continue;
    sim.heat[i] += add[i];
    if (sim.heat[i] >= opts.igniteAtHeat) igniteCell(sim, cfg, i % cfg.cols, Math.floor(i / cfg.cols), opts);
    add[i] = 0;
  }
  sim.burnt = burnt;

  // Spawns from the live front and the freshly charred band.
  for (let r = 0; r < cfg.rows; r++) {
    for (let c = 0; c < cfg.cols; c++) {
      const i = r * cfg.cols + c;
      const b = burnAt(sim, i);
      if (b > 0.06 && b < 0.62 && rand(sim) < opts.emberRate * dt) {
        spawnEmber(sim, (c + 0.5) * cw, (r + 0.5) * ch, opts);
      } else if (b >= 0.7 && b < 1 && rand(sim) < opts.ashRate * dt) {
        spawnAsh(sim, (c + 0.5) * cw, (r + 0.5) * ch, opts);
      }
    }
  }
  stepParticles(sim, cfg, dt);
}

export function stepBurn(sim: BurnState, cfg: BurnConfig, dt: number, opts: BurnOptions) {
  'worklet';
  let left = Math.min(dt, 0.1);
  while (left > 0) {
    const h = Math.min(left, opts.fixedDt);
    step(sim, cfg, h, opts);
    left -= h;
  }
}

/** Flicker for the glow band: per-cell noise breathing with the clock. */
export function flickerAt(sim: BurnState, cfg: BurnConfig, i: number): number {
  'worklet';
  return 0.7 + 0.3 * vnoise((i % cfg.cols) * 0.7 + sim.clock * 3.1, Math.floor(i / cfg.cols) * 0.7, 517);
}

/**
 * Pack the burn field for the shader/overlay: r = burn level, g = glow
 * flicker inside the burning band, b = ember-crack pulse in the char band.
 */
export function packBurn(sim: BurnState, cfg: BurnConfig, bytes: Uint8Array): Uint8Array {
  'worklet';
  const n = cfg.cols * cfg.rows;
  for (let i = 0; i < n; i++) {
    const b = burnAt(sim, i);
    const o = i * 4;
    bytes[o] = Math.round(b * 255);
    let g = 0;
    if (b > 0.02 && b < 0.5) {
      g = Math.round(255 * flickerAt(sim, cfg, i) * Math.min(1, (b - 0.02) / 0.08));
    }
    bytes[o + 1] = g;
    let crack = 0;
    if (b >= 0.5 && b < 0.98) {
      const p = vnoise((i % cfg.cols) * 1.7 + sim.clock * 0.6, Math.floor(i / cfg.cols) * 1.7, 913);
      crack = p > 0.78 ? Math.round(255 * (p - 0.78) * 3.2 * flickerAt(sim, cfg, i)) : 0;
    }
    bytes[o + 2] = crack;
    bytes[o + 3] = 255;
  }
  return bytes;
}

// Scene and palette for Burn Dismiss. The card is an original procedural
// postcard: paper with fibre, a sunset photo, handwriting lines and a stamp.
// cardScene() returns plain draw items so the native example (Skia offscreen
// surface) and the Canvas2D web preview paint the identical card.

export const CARD_W = 340;
export const CARD_H = 460;

export type SceneItem =
  | { k: "vgrad"; x: number; y: number; w: number; h: number; from: string; to: string }
  | { k: "rect"; x: number; y: number; w: number; h: number; color: string; r?: number }
  | { k: "circle"; x: number; y: number; r: number; color: string }
  | { k: "poly"; points: number[]; color: string }
  | { k: "line"; points: number[]; color: string; width: number }
  | { k: "text"; x: number; y: number; size: number; color: string; text: string; align?: "left" | "center" | "right"; bold?: boolean };

function mulberry(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function cardScene(seed = 20261124): SceneItem[] {
  const items: SceneItem[] = [];
  // Paper.
  items.push({ k: "vgrad", x: 0, y: 0, w: CARD_W, h: CARD_H, from: "#faf5ea", to: "#f0e7d2" });
  // Paper fibre: faint short strokes, seeded so every platform matches.
  const rng = mulberry(seed);
  for (let i = 0; i < 170; i++) {
    const x = rng() * CARD_W;
    const y = rng() * CARD_H;
    const len = 3 + rng() * 9;
    const ang = (rng() - 0.5) * 0.9;
    items.push({
      k: "line",
      points: [x, y, x + Math.cos(ang) * len, y + Math.sin(ang) * len],
      color: rng() > 0.5 ? "rgba(120,98,64,0.10)" : "rgba(255,255,255,0.16)",
      width: 0.8,
    });
  }
  // Photo frame.
  items.push({ k: "rect", x: 18, y: 18, w: CARD_W - 36, h: 214, color: "#ffffff", r: 10 });
  items.push({ k: "rect", x: 18.75, y: 18.75, w: CARD_W - 37.5, h: 213, color: "rgba(90,70,40,0.18)", r: 10 });
  // Photo: sunset over hills, original procedural art.
  const px = 24, py = 24, pw = CARD_W - 48, ph = 202;
  items.push({ k: "vgrad", x: px, y: py, w: pw, h: ph, from: "#ffd9a3", to: "#f2766b" });
  // Sun with halo.
  items.push({ k: "circle", x: px + pw * 0.62, y: py + ph * 0.42, r: 30, color: "rgba(255,244,200,0.55)" });
  items.push({ k: "circle", x: px + pw * 0.62, y: py + ph * 0.42, r: 19, color: "#fff3c4" });
  // Far hills.
  items.push({
    k: "poly",
    points: [px, py + ph * 0.62, px + pw * 0.18, py + ph * 0.44, px + pw * 0.38, py + ph * 0.58, px + pw * 0.55, py + ph * 0.47, px + pw * 0.74, py + ph * 0.6, px + pw, py + ph * 0.5, px + pw, py + ph * 0.78, px, py + ph * 0.78],
    color: "#96506b",
  });
  // Near hills.
  items.push({
    k: "poly",
    points: [px, py + ph * 0.74, px + pw * 0.22, py + ph * 0.58, px + pw * 0.46, py + ph * 0.72, px + pw * 0.68, py + ph * 0.6, px + pw, py + ph * 0.74, px + pw, py + ph, px, py + ph],
    color: "#5f3450",
  });
  // Water band with sun reflection.
  items.push({ k: "vgrad", x: px, y: py + ph * 0.78, w: pw, h: ph * 0.22, from: "#e88a63", to: "#b4505e" });
  for (let i = 0; i < 6; i++) {
    const w = 14 - i * 1.8;
    const y = py + ph * (0.8 + i * 0.032);
    items.push({ k: "line", points: [px + pw * 0.62 - w, y, px + pw * 0.62 + w, y], color: "rgba(255,236,180,0.5)", width: 1.6 });
  }
  // Birds.
  items.push({ k: "line", points: [px + pw * 0.3, py + ph * 0.3, px + pw * 0.3 + 5, py + ph * 0.3 - 3, px + pw * 0.3 + 10, py + ph * 0.3], color: "#4a2c3c", width: 1.4 });
  items.push({ k: "line", points: [px + pw * 0.38, py + ph * 0.24, px + pw * 0.38 + 4, py + ph * 0.24 - 2.4, px + pw * 0.38 + 8, py + ph * 0.24], color: "#4a2c3c", width: 1.2 });
  // Title and handwriting lines.
  items.push({ k: "text", x: 24, y: 268, size: 19, color: "#3c2f22", text: "Hill station, day three", bold: true });
  items.push({ k: "text", x: 24, y: 296, size: 12.5, color: "#6d5c46", text: "The fog lifted before breakfast and the" });
  items.push({ k: "text", x: 24, y: 314, size: 12.5, color: "#6d5c46", text: "whole valley turned to amber. We walked" });
  items.push({ k: "text", x: 24, y: 332, size: 12.5, color: "#6d5c46", text: "the ridge until the lamps came on." });
  items.push({ k: "text", x: 24, y: 366, size: 12.5, color: "#6d5c46", text: "Wish you were here. Keep this one" });
  items.push({ k: "text", x: 24, y: 384, size: 12.5, color: "#6d5c46", text: "somewhere safe." });
  // Divider and footer.
  items.push({ k: "line", points: [24, 412, CARD_W - 24, 412], color: "rgba(90,70,40,0.25)", width: 1 });
  items.push({ k: "text", x: 24, y: 434, size: 10.5, color: "#8a7758", text: "SUNDAY · 7:12 PM" });
  // Postmark stamp.
  items.push({ k: "circle", x: CARD_W - 52, y: 428, r: 16, color: "rgba(150,100,60,0.55)" });
  items.push({ k: "circle", x: CARD_W - 52, y: 428, r: 14, color: "#f2e9d6" });
  items.push({ k: "text", x: CARD_W - 52, y: 433, size: 13, color: "#8a5a3a", text: "54", align: "center", bold: true });
  return items;
}

import React, { useMemo, useState } from "react";
import { Pressable, Text, View } from "react-native";
import { Skia, TileMode, useTypeface, vec, type SkTypeface } from "@shopify/react-native-skia";
import { BurnDismiss } from "./BurnDismiss";
import { CARD_H, CARD_W, cardScene, type SceneItem } from "./burnDesign";

const GEIST = require("../text-morph/fonts/Geist-Regular.ttf");
const SCALE = 2;

// The card to burn: one texture drawn once with Skia at 2x.
function drawScene(typeface: SkTypeface) {
  const surface = Skia.Surface.MakeOffscreen(CARD_W * SCALE, CARD_H * SCALE);
  if (!surface) throw new Error("Unable to prepare the card texture");
  const canvas = surface.getCanvas();
  const paint = Skia.Paint();
  paint.setAntiAlias(true);
  canvas.clear(Skia.Color("#f4eddc"));
  for (const it of cardScene() as SceneItem[]) {
    if (it.k === "vgrad") {
      paint.setShader(
        Skia.Shader.MakeLinearGradient(
          vec(it.x * SCALE, it.y * SCALE),
          vec(it.x * SCALE, (it.y + it.h) * SCALE),
          [Skia.Color(it.from), Skia.Color(it.to)],
          null,
          TileMode.Clamp,
        ),
      );
      canvas.drawRect(Skia.XYWHRect(it.x * SCALE, it.y * SCALE, it.w * SCALE, it.h * SCALE), paint);
      paint.setShader(null);
    } else if (it.k === "rect") {
      paint.setColor(Skia.Color(it.color));
      if (!it.r) canvas.drawRect(Skia.XYWHRect(it.x * SCALE, it.y * SCALE, it.w * SCALE, it.h * SCALE), paint);
      else canvas.drawRRect(Skia.RRectXY(Skia.XYWHRect(it.x * SCALE, it.y * SCALE, it.w * SCALE, it.h * SCALE), it.r * SCALE, it.r * SCALE), paint);
    } else if (it.k === "circle") {
      paint.setColor(Skia.Color(it.color));
      canvas.drawCircle(it.x * SCALE, it.y * SCALE, it.r * SCALE, paint);
    } else if (it.k === "poly") {
      paint.setColor(Skia.Color(it.color));
      const path = Skia.Path.Make();
      path.moveTo(it.points[0] * SCALE, it.points[1] * SCALE);
      for (let i = 2; i < it.points.length; i += 2) path.lineTo(it.points[i] * SCALE, it.points[i + 1] * SCALE);
      path.close();
      canvas.drawPath(path, paint);
    } else if (it.k === "line") {
      paint.setColor(Skia.Color(it.color));
      paint.setStrokeWidth(it.width * SCALE);
      paint.setStyle(1);
      const path = Skia.Path.Make();
      path.moveTo(it.points[0] * SCALE, it.points[1] * SCALE);
      for (let i = 2; i < it.points.length; i += 2) path.lineTo(it.points[i] * SCALE, it.points[i + 1] * SCALE);
      canvas.drawPath(path, paint);
      paint.setStyle(0);
    } else {
      paint.setColor(Skia.Color(it.color));
      const font = Skia.Font(typeface, it.size * SCALE);
      const w = it.align === "left" || !it.align ? 0 : font.getTextWidth(it.text);
      const x = it.x * SCALE - (it.align === "center" ? w / 2 : it.align === "right" ? w : 0);
      canvas.drawText(it.text, x, it.y * SCALE, paint, font);
    }
  }
  surface.flush();
  const snapshot = surface.makeImageSnapshot();
  const copy = snapshot.makeNonTextureImage();
  snapshot.dispose();
  surface.dispose();
  paint.dispose();
  if (!copy) throw new Error("Unable to copy the card texture");
  return copy;
}

export default function Example({ onFeedback }: { onFeedback?: (event: "ignite" | "release" | "restore") => void }) {
  const [slow, setSlow] = useState(false);
  const [reduce, setReduce] = useState(false);
  const [restoreTick, setRestoreTick] = useState(0);
  const [gone, setGone] = useState(false);
  const typeface = useTypeface(GEIST);
  const scene = useMemo(() => (typeface ? drawScene(typeface) : null), [typeface]);
  React.useEffect(() => () => scene?.dispose(), [scene]);
  if (!scene) return null;
  const chip = (on: boolean) => ({
    paddingVertical: 9, paddingHorizontal: 13, borderRadius: 24, borderWidth: 1,
    backgroundColor: on ? "#315843" : "#eeeade", borderColor: on ? "#315843" : "#c7caba",
  });
  return (
    <View style={{ alignItems: "center", gap: 10, paddingVertical: 14 }}>
      <View style={{ borderRadius: 18, backgroundColor: "#241d16" }}>
        <BurnDismiss
          image={scene}
          slowMotion={slow}
          reducedMotion={reduce}
          restoreTick={restoreTick}
          onDismissed={() => setGone(true)}
          onFeedback={(e) => { if (e === "ignite") setGone(false); onFeedback?.(e); }}
        />
      </View>
      <View style={{ flexDirection: "row", gap: 8, flexWrap: "wrap", justifyContent: "center" }}>
        <Pressable accessibilityRole="button" onPress={() => setRestoreTick((v) => v + 1)} style={chip(false)}>
          <Text style={{ fontSize: 12, color: "#315843", fontFamily: "Geist-Regular" }}>Restore</Text>
        </Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: slow }} onPress={() => setSlow((v) => !v)} style={chip(slow)}>
          <Text style={{ fontSize: 12, color: slow ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Slow motion: {slow ? "on" : "off"}</Text>
        </Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: reduce }} onPress={() => setReduce((v) => !v)} style={chip(reduce)}>
          <Text style={{ fontSize: 12, color: reduce ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Reduce motion: {reduce ? "on" : "off"}</Text>
        </Pressable>
      </View>
      <Text style={{ fontSize: 12, color: "#63705f", fontFamily: "Geist-Regular" }}>
        {gone ? "Burned away. Restore to bring the card back." : "Touch to ignite. Hold to feed the fire, drag to spread it."}
      </Text>
    </View>
  );
}
